import json,numpy as np
from PIL import Image
from pathlib import Path
import sys
p=Path(sys.argv[1]);m=json.loads((p/'meta.json').read_text())
for c in m['cameras']:
 im=np.array(Image.open(p/(c+'.png'))); dep=np.load(p/('depth_'+c+'.npy')).astype(float)
 v,u=np.indices(dep.shape); k=np.array(m['cameras'][c]['intrinsic_cv']); T=np.array(m['cameras'][c]['cam2world_gl'])
 pts=np.stack([(u-k[0,2])*dep/k[0,0],-(v-k[1,2])*dep/k[1,1],-dep],-1)@T[:3,:3].T+T[:3,3]
 masks={'blue':(im[:,:,2]>im[:,:,0]*1.3)&(im[:,:,2]>im[:,:,1]*1.15)&(im[:,:,2]>70),'green':(im[:,:,1]>im[:,:,0]*1.5)&(im[:,:,1]>im[:,:,2]*1.3)&(im[:,:,1]>90)}
 print(c)
 for name,mask in masks.items():
  pp=pts[mask]
  if len(pp): print(name,len(pp),'median',np.median(pp,axis=0),'min',pp.min(0),'max',pp.max(0),'pixels',np.stack([u[mask],v[mask]],-1).min(0),np.stack([u[mask],v[mask]],-1).max(0))
 np.save(p/(c+'_xyz.npy'),pts)
 Image.fromarray(im).resize((960,720)).save(p/(c+'_large.png'))
